-- ARC · frases revisadas: se apagan todas y quedan solo estas
update public.content_quotes set active = false;
insert into public.content_quotes (id, text, who, source, why, kind, active)
select id, text, who, source, why, kind, active from jsonb_populate_recordset(null::public.content_quotes, $arc$[{"id": "q-arc-01", "text": "Un perdedor puede superar a un genio a base de esfuerzo.", "who": "Rock Lee", "source": "Naruto", "why": "Lee no podía usar ninjutsu y aun así se ganó un sitio entre los mejores. Aquí nadie necesita talento para subir de nivel.", "kind": "cita", "active": true}, {"id": "q-arc-02", "text": "No voy a huir ni a retirar mi palabra. Ese es mi camino ninja.", "who": "Naruto Uzumaki", "source": "Naruto", "why": "Si te has dicho que hoy entrenas, hoy entrenas. Cúmplete a ti misma.", "kind": "cita", "active": true}, {"id": "q-arc-03", "text": "Ve más allá. ¡Plus Ultra!", "who": "All Might", "source": "My Hero Academia", "why": "Esa última repetición con buena técnica es tu Plus Ultra de hoy.", "kind": "cita", "active": true}, {"id": "q-arc-04", "text": "Tú también puedes ser un héroe.", "who": "All Might", "source": "My Hero Academia", "why": "Se lo dijo a un chaval sin poderes. Ese chaval acabó siendo el número uno.", "kind": "cita", "active": true}, {"id": "q-arc-05", "text": "¡Entregad vuestros corazones!", "who": "Erwin Smith", "source": "Attack on Titan", "why": "Hoy dalo todo en el entreno. Mañana descansas.", "kind": "cita", "active": true}, {"id": "q-arc-06", "text": "Elige aquello de lo que menos te vayas a arrepentir.", "who": "Levi Ackerman", "source": "Attack on Titan", "why": "¿Te arrepentirás más de ir al gym cansada o de no haber ido? Ya lo sabes.", "kind": "cita", "active": true}, {"id": "q-arc-07", "text": "Tranquilo, soy el más fuerte.", "who": "Satoru Gojo", "source": "Jujutsu Kaisen", "why": "Dilo antes de ponerte bajo la barra. La confianza también se entrena.", "kind": "cita", "active": true}, {"id": "q-arc-08", "text": "¡Voy a ser el Rey de los Piratas!", "who": "Monkey D. Luffy", "source": "One Piece", "why": "Luffy lo grita desde el capítulo uno sin vergüenza. Ponle nombre a tu meta.", "kind": "cita", "active": true}, {"id": "q-arc-09", "text": "No todo el que se esfuerza triunfa, pero todo el que ha triunfado se ha esforzado.", "who": "Kamogawa", "source": "Hajime no Ippo", "why": "El esfuerzo no te asegura el resultado. Es lo único que te da opciones.", "kind": "cita", "active": true}, {"id": "q-arc-10", "text": "¡Arde, corazón!", "who": "Kyojuro Rengoku", "source": "Demon Slayer", "why": "Para cuando la motivación se apaga a mitad de entreno.", "kind": "cita", "active": true}, {"id": "q-arc-11", "text": "Cien flexiones, cien abdominales, cien sentadillas y diez kilómetros de carrera. Todos los días.", "who": "Saitama", "source": "One Punch Man", "why": "Su secreto no era ningún poder: era no saltarse ni un día.", "kind": "cita", "active": true}, {"id": "q-arc-12", "text": "Cree en ti. No en el yo que cree en ti, ni en el tú que cree en mí. Cree en el tú que cree en ti.", "who": "Kamina", "source": "Gurren Lagann", "why": "Para los días en que no te ves capaz. Simon tampoco se lo creía.", "kind": "cita", "active": true}, {"id": "q-arc-13", "text": "¡Manda la lógica a paseo y haz lo imposible!", "who": "Kamina", "source": "Gurren Lagann", "why": "Para esa serie que te da miedo intentar.", "kind": "cita", "active": true}, {"id": "q-arc-14", "text": "El talento es algo que haces florecer. El instinto es algo que pules.", "who": "Toru Oikawa", "source": "Haikyuu!!", "why": "Oikawa no era un genio y llegó arriba puliendo lo suyo cada día.", "kind": "cita", "active": true}, {"id": "q-arc-15", "text": "Una lección sin dolor no tiene sentido. Nadie gana nada sin sacrificar algo a cambio.", "who": "Edward Elric", "source": "Fullmetal Alchemist: Brotherhood", "why": "Las agujetas, el madrugón, el táper. Eso es lo que pagas a cambio.", "kind": "cita", "active": true}, {"id": "q-arc-16", "text": "No importa lo fuerte que golpees. Importa lo fuerte que te pueden golpear y seguir avanzando.", "who": "Rocky Balboa", "source": "Rocky Balboa", "why": "Una mala semana, un catarro, exámenes. Lo importante es volver el lunes.", "kind": "cita", "active": true}, {"id": "q-arc-17", "text": "Un paso a la vez, un golpe a la vez, un asalto a la vez.", "who": "Rocky Balboa", "source": "Creed", "why": "No pienses en el año entero. Piensa en esta serie.", "kind": "cita", "active": true}, {"id": "q-arc-18", "text": "Nunca dejes que nadie te diga que no puedes hacer algo. Ni siquiera yo.", "who": "Chris Gardner", "source": "En busca de la felicidad", "why": "Y menos la vocecita que te dice que eso no es para ti.", "kind": "cita", "active": true}, {"id": "q-arc-19", "text": "Hazlo o no lo hagas, pero no lo intentes.", "who": "Yoda", "source": "El Imperio contraataca", "why": "Ve a por la serie con la cabeza puesta.", "kind": "cita", "active": true}, {"id": "q-arc-20", "text": "¿Por qué nos caemos? Para aprender a levantarnos.", "who": "Thomas Wayne", "source": "Batman Begins", "why": "Un mal entreno también enseña.", "kind": "cita", "active": true}, {"id": "q-arc-21", "text": "Hay una diferencia entre conocer el camino y recorrerlo.", "who": "Morfeo", "source": "Matrix", "why": "Saber la teoría está bien. Ir al gym está mejor.", "kind": "cita", "active": true}, {"id": "q-arc-22", "text": "Odiaba cada minuto de entrenamiento, pero me decía: no abandones. Sufre ahora y vive el resto de tu vida como un campeón.", "who": "Muhammad Ali", "source": "Boxeo", "why": "Ni a Ali le apetecía siempre. Lo hacía igual.", "kind": "cita", "active": true}, {"id": "q-arc-23", "text": "Los campeones no se hacen en los gimnasios. Se hacen de algo que llevan dentro: un deseo, un sueño, una visión.", "who": "Muhammad Ali", "source": "Boxeo", "why": "El gym es donde se nota. Lo de dentro lo traes tú.", "kind": "cita", "active": true}, {"id": "q-arc-24", "text": "La fuerza no viene de ganar. Viene de tus luchas: cuando pasas por algo duro y decides no rendirte, eso es fuerza.", "who": "Arnold Schwarzenegger", "source": "Culturismo", "why": "Los días malos también te están haciendo fuerte.", "kind": "cita", "active": true}, {"id": "q-arc-25", "text": "Pelea un asalto más. Cuando tus brazos estén tan cansados que apenas puedas levantar la guardia, pelea un asalto más.", "who": "James J. Corbett", "source": "Boxeo", "why": "La serie que haces cansada es la que te cambia.", "kind": "cita", "active": true}, {"id": "q-arc-26", "text": "Cuando tu mente te dice que has terminado, solo vas por el 40%.", "who": "David Goggins", "source": "Ultrafondo", "why": "Cuando creas que no puedes más, prueba una repetición más.", "kind": "cita", "active": true}, {"id": "q-arc-27", "text": "Nadie va a venir a salvarte.", "who": "David Goggins", "source": "Ultrafondo", "why": "Duro, pero liberador: el cambio depende de ti.", "kind": "cita", "active": true}, {"id": "q-arc-28", "text": "He fallado más de 9.000 tiros en mi carrera. Por eso tengo éxito.", "who": "Michael Jordan", "source": "Baloncesto", "why": "Cada serie fallida es un dato para la siguiente.", "kind": "cita", "active": true}, {"id": "q-arc-29", "text": "Solo los disciplinados son libres.", "who": "Eliud Kipchoge", "source": "Maratón", "why": "La disciplina te ahorra decidir cada día si vas o no.", "kind": "cita", "active": true}, {"id": "q-arc-30", "text": "No temo al hombre que ha practicado 10.000 patadas una vez, sino al que ha practicado una patada 10.000 veces.", "who": "Bruce Lee", "source": "Artes marciales", "why": "Domina la sentadilla antes de buscar la variante rara.", "kind": "cita", "active": true}, {"id": "q-arc-31", "text": "Una campeona no se define por sus victorias, sino por cómo se recupera cuando cae.", "who": "Serena Williams", "source": "Tenis", "why": "La semana que fallas no cuenta. Cuenta la siguiente.", "kind": "cita", "active": true}, {"id": "q-arc-32", "text": "No soy la próxima Usain Bolt ni el próximo Michael Phelps. Soy la primera Simone Biles.", "who": "Simone Biles", "source": "Gimnasia", "why": "No entrenas para parecerte a nadie. Entrenas para ser tu mejor versión.", "kind": "cita", "active": true}, {"id": "q-arc-33", "text": "Puedo porque pienso que puedo.", "who": "Carolina Marín", "source": "Bádminton", "why": "Su lema desde niña en Huelva. Llegó a campeona olímpica.", "kind": "cita", "active": true}, {"id": "q-arc-34", "text": "El dolor es inevitable. El sufrimiento es opcional.", "who": "Haruki Murakami", "source": "De qué hablo cuando hablo de correr", "why": "Las piernas arden, pero lo que te cuentas mientras lo eliges tú.", "kind": "cita", "active": true}, {"id": "q-arc-35", "text": "Somos lo que hacemos repetidamente.", "who": "Will Durant, sobre Aristóteles", "source": "Filosofía", "why": "Un día de gym no cambia nada. Cien seguidos, sí.", "kind": "cita", "active": true}, {"id": "q-arc-36", "text": "Lo que se interpone en el camino se convierte en el camino.", "who": "Marco Aurelio", "source": "Meditaciones", "why": "Si una lesión te frena un ejercicio, trabaja lo que sí puedes.", "kind": "cita", "active": true}, {"id": "q-arc-37", "text": "No es que tengamos poco tiempo, es que perdemos mucho.", "who": "Séneca", "source": "Sobre la brevedad de la vida", "why": "Una hora de entreno es menos de lo que se va en scroll.", "kind": "cita", "active": true}, {"id": "q-arc-38", "text": "La disciplina es el puente entre las metas y los logros.", "who": "Jim Rohn", "source": "Desarrollo personal", "why": "Las ganas te traen al gym una semana. La disciplina, todo el año.", "kind": "cita", "active": true}, {"id": "q-arc-39", "text": "Cada acción que haces es un voto por la persona que quieres ser.", "who": "James Clear", "source": "Hábitos atómicos", "why": "Cada vaso de agua y cada serie cuentan como voto.", "kind": "cita", "active": true}, {"id": "q-arc-40", "text": "No subes al nivel de tus metas. Caes al nivel de tus sistemas.", "who": "James Clear", "source": "Hábitos atómicos", "why": "Por eso aquí subes de nivel con hábitos, no con propósitos de año nuevo.", "kind": "cita", "active": true}, {"id": "q-arc-41", "text": "Nadie puede hacerte sentir inferior sin tu consentimiento.", "who": "Eleanor Roosevelt", "source": "Política y activismo", "why": "Tu sitio en la zona de pesas es tuyo.", "kind": "cita", "active": true}, {"id": "q-arc-42", "text": "Atribuyo mi éxito a esto: nunca di ni acepté una excusa.", "who": "Florence Nightingale", "source": "Enfermería", "why": "La fundadora de la enfermería moderna, también en el gym.", "kind": "cita", "active": true}]$arc$::jsonb)
on conflict (id) do update set text = excluded.text, who = excluded.who, source = excluded.source, why = excluded.why, active = true;
